package ai.kstock.mobile;
import android.app.*;import android.app.job.*;import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** On-device, OS-scheduled read-only mover polling. No push token or user holdings. */
public final class MarketAlertJob extends JobService {
 public static final int ID=264;private AtomicBoolean cancelled=new AtomicBoolean(false);
 public static boolean enable(Context c,String server,int threshold,boolean up,boolean down){
  if(!ServerAddress.DEFAULT.equals(server)||threshold<1||threshold>30||(!up&&!down))return false;
  NotificationManager m=c.getSystemService(NotificationManager.class);m.createNotificationChannel(new NotificationChannel("market-movers","급상승·급하락 관측",NotificationManager.IMPORTANCE_DEFAULT));
  int status=c.getSystemService(JobScheduler.class).schedule(new JobInfo.Builder(ID,new ComponentName(c,MarketAlertJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000L).setPersisted(true).build());
  if(status!=JobScheduler.RESULT_SUCCESS)return false;
  return c.getSharedPreferences("market-alerts",MODE_PRIVATE).edit().putString("server",server).putInt("threshold",threshold).putBoolean("up",up).putBoolean("down",down).putBoolean("enabled",true).commit();
 }
 public static void disable(Context c){c.getSharedPreferences("market-alerts",MODE_PRIVATE).edit().clear().commit();c.getSystemService(JobScheduler.class).cancel(ID);c.getSystemService(NotificationManager.class).cancel(ID);}
 @Override public boolean onStartJob(JobParameters params){final SharedPreferences p=getSharedPreferences("market-alerts",MODE_PRIVATE);if(!p.getBoolean("enabled",false)||!ServerAddress.DEFAULT.equals(p.getString("server","")))return false;final AtomicBoolean stop=new AtomicBoolean(false);cancelled=stop;
  new Thread(()->{try{ApiClient client=new ApiClient(ServerAddress.DEFAULT,new TokenVault(this),new ApiClient.Network());long now=System.currentTimeMillis();JSONObject seen;try{seen=new JSONObject(p.getString("seen","{}"));}catch(Exception e){seen=new JSONObject();}List<String> remove=new ArrayList<>();Iterator<String> names=seen.keys();while(names.hasNext()){String k=names.next();if(now-seen.optLong(k,0)>=3600000L)remove.add(k);}for(String k:remove)seen.remove(k);int up=0,down=0;
   // Start both market refreshes together and wait within this job, avoiding stale-cache-only polling.
   for(int attempt=0;attempt<7;attempt++){if(stop.get()||!p.getBoolean("enabled",false))return;ApiClient.Reply warm=client.request("/api/v2/trading/movers?market=ALL","GET",null);boolean ready=false;try{JSONArray markets=new JSONObject(warm.text()).getJSONArray("markets");ready=markets.length()==2;for(int n=0;n<markets.length();n++)ready=ready&&"OBSERVED".equals(markets.getJSONObject(n).optString("dataStatus"));}catch(Exception ignored){}if(ready)break;if(attempt<6)Thread.sleep(4000);}
   for(String market:new String[]{"KR","US"}){if(stop.get()||!p.getBoolean("enabled",false))return;ApiClient.Reply reply=client.request("/api/v2/trading/movers?market="+market,"GET",null);if(reply.code!=200)continue;JSONObject d=new JSONObject(reply.text());if(!d.optBoolean("success")||!"OBSERVED".equals(d.optString("dataStatus"))||!market.equals(d.optString("market")))continue;long at=java.time.Instant.parse(d.getString("receivedAt")).toEpochMilli();if(at>now||now-at>=600000L)continue;
    for(String side:new String[]{"gainers","losers"}){boolean rising=side.equals("gainers");if(!p.getBoolean(rising?"up":"down",true))continue;JSONArray rows=d.optJSONArray(side);if(rows==null||rows.length()>10)continue;for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n);String symbol=row.optString("symbol"),exchange=row.optString("exchange");double rate=row.optDouble("changePct",Double.NaN);if(!symbol.matches(market.equals("KR")?"[0-9][A-Z0-9]{5}":"[A-Z][A-Z0-9.]{0,9}")||!Double.isFinite(rate)||(rising?rate< p.getInt("threshold",5):rate> -p.getInt("threshold",5)))continue;String key=market+":"+exchange+":"+symbol+":"+side;if(seen.has(key))continue;seen.put(key,now);if(rising)up++;else down++;}}
   }
   if(stop.get()||!p.getBoolean("enabled",false))return;NotificationManager manager=getSystemService(NotificationManager.class);if(!manager.areNotificationsEnabled())return;
   if(up+down>0){PendingIntent open=PendingIntent.getActivity(this,ID,new Intent(this,MainActivity.class).putExtra("kstock_open_movers",true),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification publicNote=new Notification.Builder(this,"market-movers").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("K-Stock").setContentText("앱에서 시장 알림을 확인하세요.").build();Notification note=new Notification.Builder(this,"market-movers").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("급상승·급하락 관측").setContentText("상승 "+up+"개 · 하락 "+down+"개가 설정 기준에 도달했습니다. 수신한 공급자 순위이며 실시간 보장이 아닙니다.").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(publicNote).build();manager.notify(ID,note);while(seen.length()>40)seen.remove(seen.keys().next());p.edit().putString("seen",seen.toString()).putLong("lastCheckedAt",now).apply();}else p.edit().putString("seen",seen.toString()).putLong("lastCheckedAt",now).apply();
  }catch(Exception ignored){}finally{if(!stop.get())jobFinished(params,false);}},"KStockMarketAlerts").start();return true;
 }
 @Override public boolean onStopJob(JobParameters params){cancelled.set(true);return true;}
}
